-- =====================================================================
-- SIGIAM-CC · Datos ficticios (fecha de corte del prototipo: 2026-11-20)
-- Copiados tal cual del script original (docs/sigiam_general.sql): los
-- INSERT de MySQL son compatibles con PostgreSQL.
-- =====================================================================
START TRANSACTION;

-- Tipos de equipo: 6 registros

-- Marcas: 9 registros

-- Ubicaciones (subestaciones): 10 registros

-- Estados operativos: 4 registros

-- Trabajadores: 8 registros

-- Equipos (inventario): 80 registros

-- Mantenimientos (2025-2026): 416 registros

COMMIT;

-- ---------------------------------------------------------------------
-- Ajuste de secuencias: como el seed inserta ids explícitos, se mueve
-- cada secuencia IDENTITY al id máximo para que los siguientes INSERT
-- (por ejemplo, desde las server actions) no choquen con la PK.
-- ---------------------------------------------------------------------
SELECT setval(pg_get_serial_sequence('tipo_equipo', 'id_tipo'),             (SELECT MAX(id_tipo) FROM tipo_equipo));
SELECT setval(pg_get_serial_sequence('marca', 'id_marca'),                  (SELECT MAX(id_marca) FROM marca));
SELECT setval(pg_get_serial_sequence('ubicacion', 'id_ubicacion'),          (SELECT MAX(id_ubicacion) FROM ubicacion));
SELECT setval(pg_get_serial_sequence('estado_operativo', 'id_estado'),      (SELECT MAX(id_estado) FROM estado_operativo));
SELECT setval(pg_get_serial_sequence('trabajador', 'id_trabajador'),        (SELECT MAX(id_trabajador) FROM trabajador));
SELECT setval(pg_get_serial_sequence('equipo', 'id_equipo'),                (SELECT MAX(id_equipo) FROM equipo));
SELECT setval(pg_get_serial_sequence('mantenimiento', 'id_mantenimiento'),  (SELECT MAX(id_mantenimiento) FROM mantenimiento));
